content.text:
The data points to a single fault in ts-train-service: its train-type database calls became very slow, and the slowness propagated up through its callers to the dashboard. I did not find a second independent fault.

```json
{
  "root_causes": [
    {
      "service": "ts-train-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, approx_quantile(duration/1e6,0.95) AS p95_ms, approx_quantile(duration/1e6,0.5) AS p50_ms FROM abnormal_traces WHERE service_name='ts-train-service' AND attr_span_kind='Client' GROUP BY 1,2,3", "claim": "In abnormal period, train-service 'SELECT ts.train_type' DB client spans have p95 about 7083 ms, median under 1 ms."},
        {"kind": "trace", "sql": "SELECT 'norm' AS p, service_name, span_name, count(*) AS n, approx_quantile(duration/1e6,0.95) AS p95_ms, approx_quantile(duration/1e6,0.5) AS p50_ms FROM normal_traces WHERE service_name='ts-train-service' AND attr_span_kind='Client' GROUP BY 1,2,3", "claim": "Normal period, the same train-service DB spans have p95 about 1.1 ms."},
        {"kind": "trace", "sql": "SELECT service_name, count(*) AS n, approx_quantile(duration/1e6,0.95) AS p95_ms FROM abnormal_traces WHERE service_name IN ('ts-train-service','ts-auth-service','ts-order-service','ts-seat-service') AND attr_span_kind='Client' AND (span_name LIKE 'SELECT%' OR span_name LIKE 'INSERT%' OR span_name LIKE 'UPDATE%') GROUP BY 1", "claim": "Other services' DB calls to mysql remain sub-2 ms p95 in abnormal period, so mysql itself is not slow."},
        {"kind": "metric", "sql": "SELECT 'abn' AS p, metric, round(avg(value),2) AS avg_v FROM abnormal_metrics_sum WHERE service_name='ts-train-service' AND metric IN ('container.cpu.time','jvm.cpu.time','jvm.memory.used','jvm.thread.count') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, round(avg(value),2) FROM normal_metrics_sum WHERE service_name='ts-train-service' AND metric IN ('container.cpu.time','jvm.cpu.time','jvm.memory.used','jvm.thread.count') GROUP BY 1,2", "claim": "Train-service CPU, JVM memory and thread counts are essentially unchanged from normal, so the process is not saturated."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-train-service", "to": "ts-basic-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-basic-service' AND s.service_name='ts-train-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "basic-service calls to train-service have p95 about 8.3 s, matching train-service's slow server time."}]},
    {"from": "ts-train-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_p95_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-travel-plan-service' AND s.service_name='ts-train-service' AND c.attr_span_kind='Client' GROUP BY 1,2", "claim": "travel-plan calls to train-service have p95 about 15 s and one errored call."}]},
    {"from": "ts-basic-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-travel-service' AND s.service_name='ts-basic-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "travel-service calls to basic-service have p95 about 27.7 s, inheriting basic's slowdown."}]},
    {"from": "ts-basic-service", "to": "ts-preserve-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-preserve-service' AND s.service_name='ts-basic-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "preserve-service calls to basic-service have p95 about 6.7 s."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "route-plan calls to travel-service have p95 about 5.6 s."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-route-plan-service' AND s.service_name='ts-travel2-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "route-plan calls to travel2-service have p95 about 5.9 s."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "travel-plan calls to route-plan have p95 about 12.5 s."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "ui-dashboard calls to travel-plan have p95 about 63.7 s, the user-visible slowdown."}]},
    {"from": "ts-travel-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "ui-dashboard calls to travel-service have p95 about 28 s."}]},
    {"from": "ts-preserve-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-preserve-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "ui-dashboard calls to preserve-service have p95 about 19.5 s."}]}
  ]
}
```

